mapper.select:
SELECT 
FROM vocabulary_theme_revision
WHERE theme_uid = #{themeUid}
  AND version = #{version}
LIMIT 1

mapper.insert:
INSERT INTO vocabulary_theme (
    theme_uid, owner_type, user_id, name, status, current_version, deleted_at
) VALUES (
    #{themeUid}, #{ownerType}, #{userId}, #{name}, #{status}, #{currentVersion}, #{deletedAt}
)

INSERT INTO vocabulary_theme_revision (
    revision_uid, theme_uid, version, name_snapshot, purpose, prompt_strategy_key, content_format_version
) VALUES (
    #{revisionUid}, #{themeUid}, #{version}, #{nameSnapshot}, #{purpose}, #{promptStrategyKey},
    #{contentFormatVersion}
)

mapper.update:
UPDATE vocabulary_theme
SET current_version = #{nextVersion},
    name = #{name},
    updated_at = CURRENT_TIMESTAMP
WHERE user_id = #{userId}
  AND theme_uid = #{themeUid}
  AND owner_type = 'user'
  AND deleted_at IS NULL
  AND current_version = #{expectedVersion}

mapper.select:
SELECT theme_uid
FROM user_vocabulary_theme_recent
WHERE user_id = #{userId}
ORDER BY last_used_at DESC, theme_uid ASC
LIMIT #{limit}
